// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // owner starts at address(0); any non-owner caller must be rejected
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.owner() == actor, "only the current owner may change ownership");
    }
}
